// Use "take" to view a sample number of records in the table and check the data.
YOUR_TABLE_HERE
| take 100

// See how many records are in the table.
YOUR_TABLE_HERE
| count

// This query returns the number of ingestions per hour in the given table.
YOUR_TABLE_HERE
| summarize IngestionCount = count() by bin(ingestion_time(), 1h)

.create-or-alter function fn_ParseWebLogs() {
logsweb
| mv-expand records
| where tostring(records.['category']) in ("AppServiceHTTPLogs", "AppServiceAppLogs")
| project 
    dateLog               = todatetime(records.['time']),
    Type                  = tostring(records.['category']),
    ResultCode            = tostring(records.properties.ScStatus),
    DurationMs            = todouble(records.properties.TimeTaken),
    Success               = toboolean(iff(records.properties.Result == "Success" or toint(records.properties.ScStatus) < 400, true, false))
//    ClientCity            = tostring(records.properties.ClientCity),            // Restera vide/null car non fourni dans les logs HTTP bruts
//    ClientCountryOrRegion = tostring(records.properties.ClientCountryOrRegion)  // Restera vide/null car non fourni dans les logs HTTP bruts
}
